  set("#relationshipDateLabel",master?"CASAMENTO":"DATA IMPORTANTE");set("#relationshipPlanKicker",master?"CASAMENTO":"PLANOS JUNTOS");set("#relationshipPlanTitle",master?"Planejamento.":"Próximos planos.");set("#relationshipDateFieldLabel",master?"Data do casamento":"Data importante");
  set("#wellnessEyebrow","BEM-ESTAR");set("#wellnessHeading","Uma prática de cada vez.");set("#wellnessDescription","Pausas, atenção e aprendizagem no seu ritmo.");if($("#wellnessGeneric"))$("#wellnessGeneric").hidden=false;
