function featureEnabled(target){const key=FEATURE_SETTINGS[target];return state.settings.navigationMode==="full"||!key||state.settings[key]!==false}
function initialsFromName(name="Meu perfil"){
  const parts=String(name).trim().split(/\s+/).filter(Boolean);if(!parts.length)return "FC";
  return (parts[0][0]+(parts.length>1?parts[parts.length-1][0]:parts[0].slice(1,2))).toUpperCase();
}
