  if($("#accountDropdownName"))$("#accountDropdownName").textContent=name;if($("#accountDropdownLogin"))$("#accountDropdownLogin").textContent=login||role;
  const topPhoto=$("#topAccountPhoto");if(topPhoto){topPhoto.src=avatar;topPhoto.hidden=false;if($("#topAccountInitials"))$("#topAccountInitials").hidden=true}
  if($("#loginProfileInitials"))$("#loginProfileInitials").textContent=initials;if($("#loginProfileName"))$("#loginProfileName").textContent=name;if($("#loginProfileRole"))$("#loginProfileRole").textContent=role;
  const loginPhoto=$("#loginProfilePhoto");if(loginPhoto){loginPhoto.src=avatar;loginPhoto.hidden=false;if($("#loginProfileInitials"))$("#loginProfileInitials").hidden=true}
  if($("#controlLastLogin"))$("#controlLastLogin").textContent=state.account?.lastLoginAt?new Date(state.account.lastLoginAt).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"}):"—";
