let draggedNVNote=null;
function renderNVQuickNotes(){const c=$('#nvQuickNotes');if(!c)return;const notes=(state.notes||[]).filter(n=>n.area==='novanilla').slice(0,12);c.innerHTML=notes.length?notes.map(n=>`<article class="nv-quick-note" draggable="true" data-nv-note="${n.id}" data-status="${n.status||'todo'}"><header><i class="status-dot ${n.status||'todo'}"></i><small>${escapeHTML(n.dueDate?formatDateBR(n.dueDate):'sem data')}</small></header><b>${escapeHTML(n.title||'Sem título')}</b><p>${escapeHTML(n.body||'')}</p></article>`).join(''):`<p class="note" style="color:#756865">Crie uma nota para o canal ou use “+ nota”.</p>`;$$('[data-nv-note]',c).forEach(card=>{card.addEventListener('dragstart',()=>{draggedNVNote=card.dataset.nvNote;card.classList.add('dragging')});card.addEventListener('dragend',()=>{draggedNVNote=null;card.classList.remove('dragging')});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();const target=card.dataset.nvNote;if(!draggedNVNote||target===draggedNVNote)return;const a=state.notes.findIndex(n=>n.id===draggedNVNote),b=state.notes.findIndex(n=>n.id===target);if(a<0||b<0)return;const [m]=state.notes.splice(a,1);state.notes.splice(b,0,m);saveState();renderNVQuickNotes();renderDashboardNotes()});card.addEventListener('dblclick',()=>showView('notes'))})}
