function applyNoteColors36(){let style=$('#noteColorsStyle36');if(!style){style=document.createElement('style');style.id='noteColorsStyle36';document.head.append(style);}style.textContent=Object.entries(state.settings.noteColors36||{}).filter(([k,v])=>NOTE_STATUS[k]&&/^#[0-9a-f]{6}$/i.test(v)).map(([k,v])=>`.status-dot.${k}{background:${v}!important}.note-card[data-status="${k}"],.dashboard-note[data-status="${k}"]{border-left:4px solid ${v}!important}`).join('');}
function noteColors36(){const defaults={done:'#31b56c',waiting:'#eac13d',todo:'#4c99d8',cancelled:'#dd5860',doing:'#ab78d1',attention:'#e8933d',later:'#987159',tomorrow:'#2c3440'};const d=document.createElement('dialog');d.className='myway-dialog';d.innerHTML='<form><h2>Cores das legendas</h2>'+Object.entries(NOTE_STATUS).map(([k,label])=>`<label style="display:flex;justify-content:space-between;margin:12px 0">${label}<input type="color" data-status-color36="${k}" value="${state.settings.noteColors36?.[k]||defaults[k]}"></label>`).join('')+'<button class="primary">Salvar cores</button><button type="button" class="ghost" data-cancel36>Cancelar</button></form>';document.body.append(d);d.showModal();d.querySelector('[data-cancel36]').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();state.settings.noteColors36=Object.fromEntries([...d.querySelectorAll('[data-status-color36]')].map(x=>[x.dataset.statusColor36,x.value]));saveState();applyNoteColors36();d.close();};d.onclose=()=>d.remove();}
