  if(name==='renderNoteArea')renderNoteArea=wrapped;else if(name==='renderDashboardNotes')renderDashboardNotes=wrapped;else if(name==='renderStickyNotes')renderStickyNotes=wrapped;else renderWorkKanban35=wrapped;
