 const originalGeneric=renderWellnessGeneric;renderWellnessGeneric=function(){originalGeneric();const rec=$('#guideRecommendation36');if(rec)rec.textContent=activeResilienceGoals34().length?'Pelas suas escolhas, experimente a pausa diante de uma vontade e registre um gatilho.':'Experimente a respiração no seu ritmo ou o jogo dos sentidos.';};
