 initDrag36();apply36();setInterval(()=>{tickFocus36();drawXP36();if(state.focus36?.until>Date.now()&&!document.body.classList.contains('auth-locked')&&!$('#view-'+state.focus36.target)?.classList.contains('active'))applyFocus36();const image=$('#meditationCorner36');if(image)image.hidden=!document.body.classList.contains('auth-locked')||$('#onboardingPanel')?.hidden===true||state.settings.animationsEnabled===false;},1000);

