 {id:'projects',title:'Ter mais foco no trabalho',description:'Kanban, prazos e uma entrega importante por vez.',priorities:['work','notes','reminders']},
 {id:'home',title:'Conquistar um bem ou uma viagem',description:'Definir uma meta, acompanhar a reserva e planejar os aportes.',priorities:['future','finance','notes']},
 {id:'procrastination52',title:'Sair da procrastinação',description:'Uma ação possível por dia, com XP e um bloco de foco opcional.',priorities:['notes','work','habits']},
 {id:'resilience52',title:'Lidar melhor com impulsos e vícios',description:'Reconhecer gatilhos, planejar alternativas e registrar suas escolhas.',priorities:['resilience','journal','meditation']},
 {id:'balance',title:'Organizar livros, filmes, séries e jogos',description:'Guardar o que quer conhecer e acompanhar o que já aproveitou.',priorities:['culture','notes','reminders']},
 {id:'study-work',title:'Estudos e trabalho',description:'Sua combinação anterior continua disponível.',priorities:['puc','work','notes'],legacy52:true}
