 home.innerHTML=`<header><div><p class="eyebrow">${daily?'SUAS PRIORIDADES DE HOJE':'SUA ÁREA DE TRABALHO'}</p><h2>${escapeHTML(daily?priorities.map(v=>V34_MODULE_NAMES[v]).join(' + '):profile.title)}</h2><p>Escolha uma ação. O restante pode esperar.</p></div><button class="ghost" type="button" id="workspaceToday38">Mudar prioridade de hoje</button></header><div class="workspace-cards38">${priorities.map((v,i)=>`<article>${illustration38(v,0)}<small>PRIORIDADE ${i+1}</small><h3>${escapeHTML(V34_MODULE_NAMES[v])}</h3><p>${escapeHTML(workspaceSummary38(v))}</p><button class="primary" type="button" data-workspace-open38="${v}">Abrir ${escapeHTML(V34_MODULE_NAMES[v])}</button></article>`).join('')}</div><footer><button class="text-button" type="button" id="workspaceMore38">${workspaceExpanded38?'Voltar ao painel simples':'Mais do painel · opcional'}</button><button class="text-button" type="button" id="workspaceAll38">${state.settings.navigationMode==='full'?'Mostrar só minhas prioridades':'Ver todas as ferramentas'}</button><span>Área habitual: ${escapeHTML(profile.title)} · <button class="text-button" type="button" id="workspaceChangeInline38">trocar área</button></span></footer>`;
 home.querySelectorAll('[data-workspace-open38]').forEach(b=>b.onclick=()=>showView(b.dataset.workspaceOpen38));$('#workspaceToday38').onclick=()=>openDailyPriority38();$('#workspaceChangeInline38').onclick=()=>chooseWorkspace38();$('#workspaceMore38').onclick=()=>{workspaceExpanded38=!workspaceExpanded38;workspaceGuideExpanded38=false;renderWorkspaceHome38();};$('#workspaceAll38').onclick=()=>setNavigationMode34(state.settings.navigationMode==='full'?'simple':'full');
