 document.body.append(d);d.querySelectorAll('[name=workspaceProfile38]').forEach(r=>r.onchange=()=>{const p=WORKSPACES38.find(x=>x.id===r.value);d.querySelectorAll('[data-workspace-custom38]').forEach((s,i)=>s.value=p.priorities[i]||'');});
