 state.workspace40 ||= {};state.workspace40.promptDate=todayISO();saveState();document.body.append(d);d.querySelectorAll('[type=checkbox]').forEach(c=>c.onchange=()=>{const n=d.querySelectorAll('[type=checkbox]:checked').length;if(n>3){c.checked=false;$('#dailyPriorityFeedback38').textContent='Escolha no máximo três. Desmarque uma para trocar.';}else $('#dailyPriorityFeedback38').textContent=n+' de 3 áreas escolhidas';});
 const finish=()=>{state.settings.tutorialSeen=true;markWorkspaceManual40();saveState();d.close();renderAll();};
