 session.technique=session.dialog.querySelector('#anxietyTechnique40')?.value||'simple';session.protocol=protocol40(session.technique,session.phaseSeconds);const cycle=session.protocol.reduce((sum,p)=>sum+p.seconds,0);session.durationSeconds=session.technique==='478'?cycle*4:Math.ceil(targetSeconds/cycle)*cycle;
