const PAYROLL_TABLE40={year:2026,inss:[[1621,.075],[2902.84,.09],[4354.27,.12],[8475.55,.14]],irrf:[[2428.8,0,0],[2826.65,.075,182.16],[3751.05,.15,394.16],[4664.68,.225,675.49],[Infinity,.275,908.73]],dependent:189.59,simplified:607.2};
const cents40=value=>Math.round((Number(value)+Number.EPSILON*Math.max(1,Math.abs(Number(value))))*100)/100;
function payrollCalc40(base,config={}){
 const salary=Math.max(0,Number(base)||0),gross=cents40(salary+Math.max(0,Number(config.taxableExtras)||0)),nontaxable=Math.max(0,Number(config.nontaxable)||0);let inss=0,previous=0;
 for(const [ceiling,rate] of PAYROLL_TABLE40.inss){inss+=Math.max(0,Math.min(gross,ceiling)-previous)*rate;previous=ceiling;}inss=cents40(inss);
 const pension=Math.max(0,Number(config.pension)||0),dependents=Math.min(30,Math.max(0,Math.floor(Number(config.dependents)||0))),legal=cents40(inss+dependents*PAYROLL_TABLE40.dependent+pension),deduction=Math.max(legal,PAYROLL_TABLE40.simplified),irBase=Math.max(0,cents40(gross-deduction)),bracket=PAYROLL_TABLE40.irrf.find(([ceiling])=>irBase<=ceiling),tax=cents40(Math.max(0,irBase*bracket[1]-bracket[2])),reduction=gross<=5000?Math.min(tax,312.89):gross<=7350?Math.min(tax,Math.max(0,cents40(978.62-.133145*gross))):0,irrf=cents40(Math.max(0,tax-reduction)),other=cents40((config.deductions||[]).reduce((sum,x)=>sum+Math.max(0,Number(x.amount)||0),0)),net=cents40(gross+nontaxable-inss-irrf-pension-other);
 return {salary,gross,nontaxable,inss,irBase,tax,reduction,irrf,other,pension,net,deduction,deductionMethod:legal>=PAYROLL_TABLE40.simplified?'Deduções legais':'Desconto simplificado',fgts:cents40(gross*.08)};
}
function payrollState40(){if(!state.payroll40||typeof state.payroll40!=='object'||Array.isArray(state.payroll40))state.payroll40={};const p=state.payroll40;p.deductions=Array.isArray(p.deductions)?p.deductions:[];return p;}
function renderPayroll40(){
 const box=$('#payrollSummary40');if(!box)return;const p=payrollState40(),r=payrollCalc40(state.settings.salaryBase,p);box.innerHTML=`<div><span>BRUTO TRIBUTÁVEL</span><strong>${money(r.gross)}</strong></div><div><span>INSS · PROGRESSIVO</span><strong>− ${money(r.inss)}</strong></div><div><span>IRRF · APÓS REDUÇÃO</span><strong>− ${money(r.irrf)}</strong></div><div><span>OUTROS DESCONTOS</span><strong>− ${money(r.other+r.pension)}</strong></div><div class="payroll-net40"><span>LÍQUIDO ESTIMADO</span><strong>${money(r.net)}</strong></div>`;
 setText40($('#payrollDetail40'),`${r.deductionMethod} na base do IRRF: ${money(r.deduction)}. Base: ${money(r.irBase)}. Redução de 2026: ${money(r.reduction)}. FGTS estimado: ${money(r.fgts)} a cargo do empregador; não descontado do líquido.`);setText40($('#payrollBasis40'),p.basis==='actual'?'O orçamento usa o líquido recebido informado.':'O orçamento usa o líquido estimado.');$('#payrollIncomeBasis40').value=p.basis||'estimate';$('#payrollActual40').value=Number(p.receivedAmount??(Number(state.settings.salaryAdvance||0)+Number(state.settings.salarySecondPayment||0)));$('#payrollActual40').closest('label').hidden=p.basis!=='actual';
}
