 $('#treeImport40').onclick=async()=>{const rows=(state.triggers36||[]).filter(r=>careAllowed38([r.context,r.first,r.next,r.impact,r.intervention,r.support].join(' ')));if(!rows.length){toast('Nenhuma cadeia disponível. Crie caixas ou registre uma cadeia abaixo.');return;}const r=await openFormDialog({title:'Trazer uma cadeia para o mapa',description:'O registro original será preservado.',fields:[{key:'id',label:'Cadeia',options:rows.map(x=>({value:x.id,label:x.context+' · '+formatDateBR(x.date)}))}]});if(!r)return;const old=rows.find(x=>x.id===r.id),t=triggerTreeState40(),offset=Math.max(20,...t.nodes.map(n=>(Number(n.y)||0)+185)),sequence=[[old.context,'trigger'],[old.first,'behavior'],[old.next,'behavior'],[old.impact,'consequence'],[old.intervention,'alternative']].filter(([title])=>title);const nodes=sequence.map(([title,type],i)=>({id:cryptoId(),title,type,x:30+i*255,y:offset,note:type==='alternative'?old.support||'':''}));t.nodes.push(...nodes);for(let i=1;i<nodes.length;i++)treeConnect40(nodes[i-1].id,nodes[i].id);saveState();renderTriggerTree40();};
 $('#treeCanvas40').addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-tree-drag40]');if(!handle||e.button!==0||treeDrag40)return;const el=handle.closest('[data-tree-node40]'),n=triggerTreeState40().nodes.find(n=>n.id===el.dataset.treeNode40);if(!n)return;e.preventDefault();treeDrag40={node:n,element:el,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,originX:Number(n.x)||0,originY:Number(n.y)||0,lastX:Number(n.x)||0,lastY:Number(n.y)||0};handle.setPointerCapture?.(e.pointerId);el.classList.add('dragging40');});
