function personalRows40(){const p=personalState40(),rows=[...PERSONAL_VIDEOS40,...p.videos].filter(v=>youtubeId40(v.videoId||v.url)&&(!p.theme||p.theme==='all'||v.themes?.includes(p.theme)));const preferred=p.theme&&p.theme!=='all'?p.theme:effectivePriorities38().includes('puc')||effectivePriorities38().includes('work')?'focus':'habits';const relevance=v=>(v.themes?.includes(preferred)?5:0)+(v.themes?.includes('resilience')&&activeResilienceGoals34().length?2:0);return rows.sort((a,b)=>p.order==='views'?(b.views??-1)-(a.views??-1):p.order==='likes'?(b.likes??-1)-(a.likes??-1):relevance(b)-relevance(a));}
