 const oldTree=renderTriggerTree40;renderTriggerTree40=function(){oldTree();renderCarePalette41();if(treeDrag40)return;$('#treeCanvas40')?.querySelectorAll('[data-tree-node40]').forEach(el=>{const n=treeVisibleNodes40().find(x=>x.id===el.dataset.treeNode40);if(!n||!['trigger','behavior'].includes(n.type))return;const b=document.createElement('button');b.type='button';b.className='tree-avoid41';b.textContent='Escolhi outro caminho';b.onclick=()=>recordAvoidedTree41(n.id);el.append(b);});};
 const cat=document.createElement('details');cat.id='resilienceCat41';cat.className='resilience-cat41';cat.innerHTML='<summary><svg viewBox="0 0 100 90" aria-hidden="true"><path class="cat-body41" d="M24 36L20 12L40 24Q50 20 60 24L80 12L76 36Q90 45 78 65Q72 78 50 78Q28 78 22 65Q10 45 24 36Z" fill="currentColor"/><path d="M34 45q5 -7 10 0M56 45q5 -7 10 0" fill="none" stroke="var(--cat-stroke41)" stroke-width="4" stroke-linecap="round"/><path d="M46 55h8l-4 5z" fill="var(--cat-stroke41)"/><path d="M50 60q-6 10 -12 1M50 60q6 10 12 1" fill="none" stroke="var(--cat-stroke41)" stroke-width="3" stroke-linecap="round"/><g class="cat-stars41"><path d="M6 22v10M1 27h10M92 22v10M87 27h10" fill="none" stroke="currentColor" stroke-width="3"/></g></svg><span>Meu progresso<small id="catProgress41"></small></span><span aria-hidden="true">⌄</span></summary><div><p id="catMessage41" role="status"></p><small id="catXp41"></small></div>';
 $('#triggerTree40').before(cat);
 const oldRecord=recordResilience35;recordResilience35=function(values){const result=oldRecord(values);if(result&&values.outcome==='pause')celebrateCat41(result.delta);return result;};
 const oldResilience=renderResilience34;renderResilience34=function(){oldResilience();renderCarePalette41();renderCat41();};
 const oldRender=renderAll;renderAll=function(...args){oldRender(...args);applySidebar41();renderCat41();};
 if(window.ResizeObserver){const observer=new ResizeObserver(()=>drawTreeEdges40());observer.observe($('#treeCanvas40').parentElement);}
 const instructions=document.createElement('p');instructions.className='note';instructions.textContent='Suas escolhas também ficam disponíveis como caixas prontas no mapa. Cada caixa nova reconhece 5 XP e cada ligação nova, 10 XP. Registros adicionais de gatilhos evitados no mesmo dia reconhecem 3 XP.';$('#resilienceSettingsCard34')?.append(instructions);
 LEARNING_GUIDES37.push({id:'care-map41',view:'resilience',title:'Dos cuidados ao mapa e à próxima escolha',description:'Use caixas prontas, reconheça relações e registre outro caminho.',steps:[{title:'Traga seus cuidados',target:'#carePalette41',text:'Os temas que você escolheu cuidar aparecem como caixas prontas. Toque em um para adicioná-lo ao mapa; você pode alterar os detalhes ou remover depois.'},{title:'Reconheça uma ligação',target:'#treeConnectForm40',text:'Ligue duas caixas quando perceber uma relação. Cada ligação nova reconhece 5 XP, até cinco por dia. Apagar e refazer a mesma relação não repete o prêmio.'},{title:'Registre outro caminho',target:'#resilienceCat41',text:'Ao evitar seguir um gatilho, escolha Registrar minha escolha. O gatinho comemora a pausa; o primeiro registro por assunto e dia reconhece XP. Novos registros ficam no histórico.'}],practice:'choice',question:'O que acontece quando você apaga e refaz a mesma ligação no mesmo dia?',options:['O mapa muda, mas o prêmio daquela relação não se repete.','O mesmo prêmio pode ser repetido sem limite.'],answer:0});refreshLearning37();applySidebar41();renderTriggerTree40();renderCat41();
