function suggestionRows41(){const priority=effectivePriorities38();return SUGGESTED_TASKS41.filter(x=>!(state.dismissedSuggestions41||[]).includes(x.id)&&!(state.notes||[]).some(n=>n.suggestion41===x.id)).sort((a,b)=>Number(priority.includes(b.view))-Number(priority.includes(a.view))).slice(0,3);}
function addSuggestion41(id){const item=SUGGESTED_TASKS41.find(x=>x.id===id);if(!item||(state.notes||[]).some(n=>n.suggestion41===id))return false;const note={id:cryptoId(),title:item.title,body:item.body,area:item.area,status:'todo',pinned:false,mainDate40:todayISO(),suggestion41:id,createdAt:new Date().toISOString()};state.notes.unshift(note);saveState();renderNotes();renderMainPostits40();renderSuggestions41();return true;}
