function sourceUrl57(raw){try{const u=new URL(String(raw));if(u.protocol!=='https:'||u.username||u.password)return '';const h=u.hostname.toLowerCase();if(['www.youtube.com','youtube.com','m.youtube.com','youtu.be','ed.ted.com','www.ted.com','ted.com'].includes(h)){if(h.includes('youtube')||h==='youtu.be')return youtubeId40(raw)?'https://www.youtube.com/watch?v='+youtubeId40(raw):'';return u.href;}return '';}catch{return '';}}
function validateCatalog57(data){
 if(!data||data.schema!==1||!Array.isArray(data.videos)||data.videos.length>100)throw Error('Use um catálogo JSON com schema 1 e no máximo 100 vídeos.');const ids=new Set();
 const rows=data.videos.map(v=>{if(!v||typeof v.id!=='string'||!/^[-a-zA-Z0-9_]{1,80}$/.test(v.id)||ids.has(v.id))throw Error('Cada vídeo precisa de um identificador único.');ids.add(v.id);const url=sourceUrl57(v.url),title=String(v.title||'').trim(),themes=Array.isArray(v.themes)?v.themes.filter(t=>t!=='all'&&TOPICS57[t]):[];if(!url||!title||title.length>160||!themes.length)throw Error('Confira título, link seguro do YouTube/TED e temas de cada vídeo.');return {id:v.id,title,url,author:String(v.author||'').slice(0,100),themes:[...new Set(themes)],language:String(v.language||'').slice(0,80),nextStep:String(v.nextStep||'').slice(0,300)};});
 return {schema:1,revision:String(data.revision||'').slice(0,40),videos:rows};
}
