/* v59: reconcile history silently; reward activity transitions, not UI saves. */
let rewardBaseline59=null;
function rewardCandidates59(){
 const rows=new Map(),add=(key,xp,label,date,evidence,eligible)=>rows.set(key,{key,xp,label,date,evidence:JSON.stringify(evidence),eligible:!!eligible});
 for(const [date,d] of Object.entries(state.days||{})){
  for(const [field,xp,label] of [['morningNoScroll',10,'Rotina da manhã'],['studyMinimum',20,'Estudo realizado'],['careerAction',15,'Ação profissional'],['preparedTomorrow',10,'Amanhã organizado'],['cbtFiveMinute',8,'Começo de cinco minutos'],['cbtThoughtCheck',8,'Reflexão registrada'],['cbtIfThen',8,'Plano registrado'],['meditated',10,'Meditação realizada']])add(`habit:${date}:${field}`,xp,label,date,!!d[field],d[field]);
  for(const [field,id,xp,label] of [['waterCups','water',2,'Primeiro copo de água'],['walkMinutes','walk',3,'Começou a caminhar'],['pagesRead','reading',3,'Primeiras páginas lidas']])add(`small36:${date}:${id}`,xp,label,date,Number(d[field])||0,Number(d[field])>0);
  for(const [field,id,goal,fallback,label] of [['waterCups','water','waterGoalCups',8,'Meta de água'],['walkMinutes','walk','walkGoalMinutes',20,'Caminhada realizada']])add(`habit:${date}:${id}`,10,label,date,Number(d[field])||0,Number(d[field])>=Math.max(1,Number(state.settings[goal])||fallback));
  for(const [field,id,limit,xp,label] of [['returns','return',10,2,'Retomada do foco'],['studyPomodoros','pomodoro',3,10,'Ciclo de estudo']])for(let n=1;n<=limit;n++)add(`${id}:${date}:${n}`,xp,label,date,Number(d[field])||0,Number(d[field])>=n);
 }
 for(const task of state.pucTrackModules||[])add(`task:${task.id}`,15,task.title||'Tarefa de estudo',activeDate,!!task.done,task.done);
 for(const note of state.notes||[])add(`note:${note.id}`,15,note.title||'Tarefa concluída',note.date||activeDate,note.status==='done',note.status==='done');
 for(const r of state.resilience34.records)if(r.outcome==='pause')add(`resilience:${r.date}:${r.goalId}`,[8,12,18][Math.min(3,Math.max(1,Number(r.priority)||1))-1],'Pausa e alternativa reconhecidas',r.date,true,true);
 for(const r of state.gymSessions)add(`gym:${r.date}`,25,'Treino registrado',r.date,true,true);
 for(const r of state.nvContent||[])add(`publish:${r.id}`,30,r.title||'Conteúdo publicado',r.publishedAt||r.date||activeDate,r.status==='published',r.status==='published');
 return rows;
}
function syncRewardXP34(){
 normalize34();const rows=rewardCandidates59(),owner=typeof cloudOwner53==='string'?cloudOwner53:'',locked=document.body.classList.contains('auth-locked'),applying=typeof cloudApplying53!=='undefined'&&cloudApplying53;
 const baseline=rewardBaseline59,changedAccount=!baseline||baseline.state!==state||baseline.owner!==owner;
 const english=Math.max(0,Math.round(Number(state.englishXP||0)/2)),before=rewardTotal34();
 if(changedAccount||locked||applying){
  // Only the first legacy migration credits old records. Normal reloads and
  // remote hydration never manufacture missing rewards or replay effects.
  if(!state.meta.rewardsV34Initialized){for(const row of rows.values())if(row.eligible)grantReward34(row.key,row.xp,row.label,row.date);state.rewards34.englishHighWater=Math.max(Number(state.rewards34.englishHighWater)||0,english);}
  state.meta.rewardsV34Initialized=true;rewardBaseline59={state,owner,rows,english};return 0;
 }
 const earned=[];
 for(const row of rows.values()){
  const previous=baseline.rows.get(row.key);
  if(row.eligible&&(!previous||!previous.eligible)&&(!previous||previous.evidence!==row.evidence)&&grantReward34(row.key,row.xp,row.label,row.date))earned.push(row);
 }
 if(english>baseline.english)state.rewards34.englishHighWater=Math.max(Number(state.rewards34.englishHighWater)||0,english);
 rewardBaseline59={state,owner,rows,english};state.meta.rewardsV34Initialized=true;
 const delta=rewardTotal34()-before;
 if(delta>0&&!resilienceSaving34){const unlocked=REWARDS34.filter(r=>r.xp>before&&r.xp<=before+delta).map(r=>r.name);celebrateXP34(delta,unlocked.length?'Desbloqueado: '+unlocked.join(', '):earned.at(-1)?.label||'Prática de inglês realizada');}
 if(earned.some(r=>/^(note:|task:|pomodoro:|publish:)/.test(r.key)))playSound58('complete');
 return delta;
}
