function routineMatchesR1(r,date){if(date<(r.start||'0000-00-00')||r.end&&date>r.end)return false;const [y,m,d]=date.split('-').map(Number);return r.cadence==='weekly'?r.weekdays?.includes(new Date(y,m-1,d,12).getDay()):d===Math.min(Number(r.monthDay)||1,new Date(y,m,0).getDate());}
