 for(const r of workRoutinesR1())if(r.enabled!==false)for(let d=1;d<=days;d++){const date=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,id='routineR1:'+r.id+':'+date;if(!routineMatchesR1(r,date)||known.has(id))continue;state.notes.push({id,area:'work',title:r.title,body:r.description||'',status:'todo',pinned:false,dueDate:date,routineIdR1:r.id,routineTimeR1:r.time||'',createdAt:new Date().toISOString(),completedAt:''});known.add(id);added++;}
