function resizeCoverR2(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{const W=1400,H=420,ratio=Math.max(W/img.naturalWidth,H/img.naturalHeight),sw=W/ratio,sh=H/ratio,sx=(img.naturalWidth-sw)/2,sy=(img.naturalHeight-sh)/2,c=document.createElement('canvas');c.width=W;c.height=H;c.getContext('2d').drawImage(img,sx,sy,sw,sh,0,0,W,H);resolve(c.toDataURL('image/jpeg',.78))}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('image'))};img.src=url;});}
